import { createTag } from '../../../utils/utils.js';
import { logWarning } from '../../../utils/lana-log.js';

/*
 * Generated by site-to-da (clone mode). Authoring:
 *   row 1 (optional): a link to a looping background MP4 (https only)
 *   last row: the hero text content
 */
const VIDEO_RE = /^https:\/\/[^\s"'<>]+\.mp4(\?[^\s"'<>]*)?$/i;

export default async function init(el) {
  const rows = [...el.querySelectorAll(':scope > div')];
  if (!rows.length) {
    logWarning('event-hero', 'no content rows');
    el.remove();
    return;
  }

  const textRow = rows[rows.length - 1];
  const mediaRow = rows.length > 1 ? rows[0] : null;
  const cells = [...textRow.querySelectorAll(':scope > div')];
  cells.forEach((cell) => cell.classList.add('event-hero-text'));
  const content = createTag('div', { class: 'event-hero-content' }, cells);

  const children = [];
  // Milo may already have swapped the MP4 link for an adobetv iframe; read the URL from either.
  const href = mediaRow?.querySelector('a')?.href || mediaRow?.querySelector('iframe')?.getAttribute('src') || '';
  if (VIDEO_RE.test(href)) {
    const video = createTag('video', {
      class: 'event-hero-video', loop: '', playsinline: '', preload: 'metadata', 'aria-hidden': 'true',
    });
    video.muted = true;
    video.src = href;
    // Respect reduced motion: show the first frame instead of autoplaying.
    if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      video.autoplay = true;
      video.play?.().catch(() => {});
    }
    children.push(createTag('div', { class: 'event-hero-media' }, video));
  }
  children.push(content);
  el.replaceChildren(...children);
}
